# Find cells now that dimensions are clear
def find_cells(grid, color):
    cells = []
    h = len(grid)
    w = len(grid[0]) if grid else 0
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color:
                cells.append((i, j))
    return cells

