def find_hollow_square(grid, rows_offset=3):
    """Check if grid is a hollow square of given dimension with row at rows_offset"""
    if rows_offset < 0 or rows_offset + rows_offset + 2 >= len(grid):
        return False
    h, w = len(grid), len(grid[0])
    if rows_offset != 3:  # Only checking 3x3 hollow squares
        return False

