    for r in range(4):  # rows 0-3
        for c in range(4):  # cols 0-3
            if r in [0, 3] or c in [0, 3]:
                if grid[r][c] == 0:
                    return False

    # Count cells (should be 8)
    count = sum(1 for r in range(4) for c in range(4) if grid[r][c] == 1)
    return count == 8

