def is_hollow_rect(grid, color):
    """Find all hollow rectangles of a given color in the grid"""
    cells = find_cells(grid, color)
    if not cells:
        return []

    results = []

    # Get unique bounding boxes
    bboxes = set()
    for r, c in cells:
        bboxes.add((r, c))

    # Try each possible rectangle size
    for height in range(3, min(len(grid)+1, 10)):
        for width in range(3, min(len(grid[0])+1, 10)):
            # Check each position
            for r in range(height - 2):  # Need space for top/bottom rows
                for c in range(width - 2):  # Need space for left/right cols
                    # Check if this forms a hollow rect
                    rect_cells = []
                    for i in range(height):
                        for j in range(width):
                            if i == 0 or i == height-1 or j == 0 or j == width-1:
                                rect_cells.append((r + i, c + j))

                    # Check all edge cells exist
                    is_hollow = all((rr, cc) in cells for rr, cc in rect_cells)
                    if is_hollow:
                        rect_cells = set(rect_cells)
                        # Get all cells in this rect
                        rect_all = set((rr, cc) for rr in range(r, r + height) 
                                      for cc in range(c, c + width))
                        # Only consider if rect is mostly empty inside
                        if rect_cells.intersection(rect_all) == rect_cells:
                            # This is a hollow rect at this position
                            # But we want the MAX rectangle for this color
                            pass

    # Simpler: for each color, find if ALL cells form a hollow rect
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            # Try this as top-left of hollow rect
            bbox_r = [x[0] for x in cells]
            bbox_c = [x[1] for x in cells]
            min_r, max_r = min(bbox_r), max(bbox_r)
            min_c, max_c = min(bbox_c), max(bbox_c)

            # Check if spans a rect
            if min_r != r or max_r != r + max_r - min_r or min_c != c or max_c != c + max_c - min_c:
                continue

            # Verify it's a hollow rect
            edge_cells = []
            for i in range(min_r, max_r + 1):
                for j in range(min_c, max_c + 1):
                    if i == min_r or i == max_r or j == min_c or j == max_c:
                        edge_cells.append((i, j))

            if set(edge_cells) == cells:
                return True  # This color forms a hollow rectangle

    return False

